function longestRepaintRun(planks, k) {
  const counts = new Array(26).fill(0)
  let left = 0
  let maxCount = 0
  for (let r = 0; r < planks.length; r++) {
    const c = planks.charCodeAt(r) - 65
    counts[c]++
    maxCount = Math.max(maxCount, counts[c])
    if (r - left + 1 - maxCount > k) {
      counts[planks.charCodeAt(left) - 65]--
      left++
    }
  }
  return planks.length - left
}
